// cli.mjs — argparse-compatible CLI parsing for the test2 port.
//
// Replicates the Python argparse behavior of the reference program:
//   parser.add_argument('--a', required=True)
// Usage/help/error text, stream choice (stdout vs stderr), and exit
// codes match CPython 3.13 argparse byte-for-byte (verified against
// the reference executable).

// os.path.basename equivalent: everything after the last '/'.
function basename(p) {
  let last = -1;
  for (let i = 0; i < p.length; i++) {
    if (p[i] === '/') last = i;
  }
  return p.slice(last + 1);
}

// Python repr() of a string, used for the %r in the
// "ignored explicit argument" error message.
function pyRepr(s) {
  const hasSingle = s.indexOf("'") !== -1;
  const hasDouble = s.indexOf('"') !== -1;
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    const code = ch.codePointAt(0);
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + quote;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\t') out += '\\t';
    else if (ch === '\r') out += '\\r';
    else if (code < 32 || code === 127) {
      const hex = code.toString(16);
      out += '\\x' + (hex.length < 2 ? '0' + hex : hex);
    } else {
      out += ch;
    }
  }
  return out + quote;
}

function isDigit(ch) {
  return ch >= '0' && ch <= '9';
}

// argparse's negative-number matcher: ^-\d+$ or ^-\d*\.\d+$
function looksLikeNegativeNumber(s) {
  if (s.length < 2 || s[0] !== '-') return false;
  const rest = s.slice(1);
  // ^\d+$
  let allDigits = rest.length > 0;
  for (const ch of rest) {
    if (!isDigit(ch)) { allDigits = false; break; }
  }
  if (allDigits) return true;
  // ^\d*\.\d+$
  const dot = rest.indexOf('.');
  if (dot === -1) return false;
  for (let i = 0; i < dot; i++) {
    if (!isDigit(rest[i])) return false;
  }
  if (dot + 1 >= rest.length) return false;
  for (let i = dot + 1; i < rest.length; i++) {
    if (!isDigit(rest[i])) return false;
  }
  return true;
}

// Mirrors argparse._parse_optional: would this string be treated as an
// option string (rather than a positional/value)? This parser has no
// options that look like negative numbers, so negative numbers and
// strings containing a space count as values; a lone '-' is a value.
function looksLikeOption(s) {
  if (s.length === 0 || s[0] !== '-') return false;
  if (s === '-') return false;
  if (looksLikeNegativeNumber(s)) return false;
  if (s.indexOf(' ') !== -1) return false;
  return true;
}

const LONG_OPTIONS = ['--help', '--a'];

// Parse argv (process.argv.slice(2)). Returns { a: string } on success.
// On any error, prints usage+error to stderr and exits with code 2.
// On -h/--help, prints help to stdout and exits with code 0.
export function parseArgs(argv) {
  const prog = basename(process.argv[1] || '');
  const usage = 'usage: ' + prog + ' [-h] --a A\n';
  const help = usage +
    '\n' +
    'options:\n' +
    '  -h, --help  show this help message and exit\n' +
    '  --a A\n';

  function error(msg) {
    process.stderr.write(usage);
    process.stderr.write(prog + ': error: ' + msg + '\n');
    process.exit(2);
  }

  function printHelp() {
    process.stdout.write(help);
    process.exit(0);
  }

  let a;
  let aSeen = false;
  const extras = [];

  let i = 0;
  while (i < argv.length) {
    const arg = argv[i];

    // '--' stops option parsing; it and everything after it are
    // reported as unrecognized arguments (Python 3.13 behavior).
    if (arg === '--') {
      while (i < argv.length) {
        extras.push(argv[i]);
        i++;
      }
      break;
    }

    if (arg.startsWith('--')) {
      // Long option, possibly in --opt=value form.
      let name = arg;
      let explicitValue = null;
      const eq = arg.indexOf('=');
      if (eq !== -1) {
        name = arg.slice(0, eq);
        explicitValue = arg.slice(eq + 1);
      }
      // Exact match or unambiguous abbreviation (allow_abbrev=True).
      let matched = null;
      for (const opt of LONG_OPTIONS) {
        if (opt === name) { matched = opt; break; }
        if (opt.startsWith(name)) {
          if (matched !== null) { matched = 'ambiguous'; break; }
          matched = opt;
        }
      }
      if (matched === '--help') {
        if (explicitValue !== null) {
          error('argument -h/--help: ignored explicit argument ' +
            pyRepr(explicitValue));
        }
        printHelp();
      } else if (matched === '--a') {
        if (explicitValue !== null) {
          a = explicitValue;
          aSeen = true;
        } else {
          const next = i + 1 < argv.length ? argv[i + 1] : null;
          if (next === null || looksLikeOption(next)) {
            error('argument --a: expected one argument');
          }
          a = next;
          aSeen = true;
          i++;
        }
      } else {
        // Unknown long option (or, impossibly here, ambiguous).
        extras.push(arg);
      }
    } else if (arg.length > 1 && arg[0] === '-' && !looksLikeNegativeNumber(arg) &&
               arg.indexOf(' ') === -1) {
      // Short-option cluster. Only -h is defined; once -h consumes the
      // cluster head, any unknown tail is dropped into extras — but the
      // help action fires first and exits, so it is never reported.
      if (arg[1] === 'h') {
        const tail = arg.slice(2);
        if (tail.startsWith('=')) {
          error('argument -h/--help: ignored explicit argument ' +
            pyRepr(tail.slice(1)));
        }
        printHelp();
      } else {
        extras.push(arg);
      }
    } else {
      // Positional, lone '-', negative number, or string with a space:
      // this parser defines no positionals, so it is an extra.
      extras.push(arg);
    }
    i++;
  }

  if (!aSeen) {
    error('the following arguments are required: --a');
  }
  if (extras.length > 0) {
    error('unrecognized arguments: ' + extras.join(' '));
  }
  return { a };
}

